import sys,subprocess,random
from pathlib import Path
sys.path.insert(0,'/app');import adjudicate as a

def walk(n):
 yield n
 for c in n.children():yield from walk(c)
def replace(n,target,value):
 if n is target:return value
 if not n.constructed:return n.raw
 content=b''.join(replace(c,target,value) for c in n.children())
 return a.tlv(n.cls,n.constructed,n.number,content)
def mutate_string(n):
 v=a.string_contents(n,n.number)
 if n.number==3:
  # Only the last component can contain unused bits.
  mid=(len(v)-1)//2+1
  pieces=[b'\0'+v[1:mid],v[:1]+v[mid:]]
 else:
  mid=len(v)//2;pieces=[v[:mid],v[mid:]]
 return a.tlv(n.cls,True,n.number,b''.join(a.tlv(0,False,n.number,x) for x in pieces))

base=a.adjudicate(Path('/app/corpus/o0011.der').read_bytes())[0]
root=a.Reader(base).read()
cases=[]
for n in walk(root):
 tag=a.der_tag(n.cls,n.constructed,n.number)
 enc_len=a.der_length(n.length)
 long_len=(bytes([129,n.length]) if n.length<128 else bytes([enc_len[0]+1,0])+enc_len[1:])
 cases.append((f'length at {n.start}',replace(root,n,tag+long_len+n.value),True))
 if n.constructed:
  cases.append((f'indef at {n.start}',replace(root,n,tag+b'\x80'+n.value+b'\0\0'),True))
 if n.is_type(2):
  sign=b'\xff' if n.value[0]&128 else b'\0'
  cases.append((f'int at {n.start}',replace(root,n,a.tlv(0,False,2,sign+n.value)),True))
 if n.cls==0 and n.number in [3,4]:
  cases.append((f'constructed at {n.start}',replace(root,n,mutate_string(n)),True))
 if n.is_type(17):
  cases.append((f'set reverse at {n.start}',replace(root,n,a.tlv(0,True,17,b''.join(c.raw for c in reversed(n.children())))),True))
  cases.append((f'set repeat at {n.start}',replace(root,n,a.tlv(0,True,17,b''.join(c.raw+c.raw for c in n.children()))),False))
 if n.is_type(4):
  # Fuzz embedded values, not just their OCTET STRING wrapper.
  try:
   sub=a.Reader(n.value).read()
   if sub.end==n.length and sub.constructed:
    for child in walk(sub):
     tag=a.der_tag(child.cls,child.constructed,child.number)
     l=a.der_length(child.length)
     ll=bytes([129,child.length]) if child.length<128 else bytes([l[0]+1,0])+l[1:]
     val=replace(sub,child,tag+ll+child.value)
     cases.append((f'embedded length at {n.start}/{child.start}',replace(root,n,a.tlv(0,False,4,val)),True))
     if child.is_type(2):
      val=replace(sub,child,a.tlv(0,False,2,b'\0'+child.value))
      cases.append((f'embedded int at {n.start}/{child.start}',replace(root,n,a.tlv(0,False,4,val)),True))
     if child.is_type(17):
      val=replace(sub,child,a.tlv(0,True,17,b''.join(c.raw for c in reversed(child.children()))))
      cases.append((f'embedded set at {n.start}/{child.start}',replace(root,n,a.tlv(0,False,4,val)),True))
  except a.BERError:pass
errors=[]
for i,(name,data,equivalent) in enumerate(cases):
 p=Path('/tmp/probe.der');p.write_bytes(data)
 want=subprocess.run(['/app/appliance/accepts',str(p)],capture_output=True,text=True).stdout.strip()
 der,offset=a.adjudicate(data)
 got='accept' if offset is None else f'reject {offset}'
 if want!=got:errors.append((name,want,got))
 if equivalent and der!=base:errors.append((name,'canonical mismatch',len(der)))
 if a.adjudicate(der)[0]!=der:errors.append((name,'idempotence failed'))
print(len(cases),'cases;',len(errors),'errors')
for error in errors[:50]:print(error)
assert not errors
